      INTO problems
      FROM expected e
      LEFT JOIN pg_class c ON c.relname=e.table_name
      LEFT JOIN pg_namespace n ON n.oid=c.relnamespace AND n.nspname='public'
      LEFT JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname=e.column_name AND a.attnum>0 AND NOT a.attisdropped
     WHERE a.attname IS NULL OR format_type(a.atttypid,a.atttypmod)<>e.type_name OR a.attnotnull<>e.not_null;
    IF problems IS NOT NULL THEN RAISE EXCEPTION 'Несоответствие столбцов:%',E'\n'||problems; END IF;

