    SELECT string_agg(c.relname||'.'||a.attname,', ')
      INTO problems
      FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped
      LEFT JOIN expected e ON e.table_name=c.relname AND e.column_name=a.attname
     WHERE n.nspname='public' AND c.relkind='r' AND e.column_name IS NULL;
    IF problems IS NOT NULL THEN RAISE EXCEPTION 'Лишние столбцы: %',problems; END IF;

    SELECT string_agg(table_name,', ') INTO problems
      FROM information_schema.tables
     WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name NOT IN ('companies', 'branches', 'locations', 'doctors', 'doctor_locations', 'patients', 'users', 'appointments', 'surveys', 'examinations', 'cbc_results', 'biochemistry_results', 'urinalysis_results', 'albuminuria_results', 'ultrasound_results', 'calculated_metrics', 'ckd_prognosis_results', 'appointment_diets', 'prescriptions', 'icd10_diagnoses', 'appointment_icd10_diagnoses', 'medications', 'appointment_additional_studies', 'audit_events', 'audit_event_changes', 'schedule_entries', 'ckd_registry_entries', 'ckd_registry_outcomes');
    IF problems IS NOT NULL THEN RAISE EXCEPTION 'Лишние таблицы core: %',problems; END IF;

    WITH expected(name) AS (VALUES ('chk_albuminuria_category'), ('chk_albuminuria_units'), ('chk_albuminuria_values'), ('chk_appointment_icd10_diagnoses_type'), ('chk_appointments_age_at_appointment'), ('chk_appointments_not_future'), ('chk_biochemistry_non_negative'), ('chk_calculated_metrics_ckd_stage'), ('chk_calculated_metrics_values'), ('chk_cbc_non_negative'), ('chk_ckd_prognosis_calculated_sources'), ('chk_ckd_prognosis_categories'), ('chk_ckd_prognosis_combined_category'), ('chk_ckd_prognosis_source_interval'), ('chk_examinations_anthropometry'), ('chk_examinations_bed_position'), ('chk_examinations_bed_position_details'), ('chk_examinations_body_temperature'), ('chk_examinations_bp'), ('chk_examinations_consciousness'), ('chk_examinations_constitution_type'), ('chk_examinations_general_condition'), ('chk_examinations_heart_rate'), ('chk_examinations_kidney_palpation'), ('chk_examinations_kidney_palpation_details'), ('chk_examinations_pasternatsky_pair'), ('chk_examinations_pasternatsky_result'), ('chk_examinations_pasternatsky_side'), ('chk_patients_birth_date_reasonable'), ('chk_ultrasound_values'), ('chk_urinalysis_non_negative'), ('chk_users_role_model'), ('ck_albuminuria_daily_albumin_excretion_nonnegative'), ('ck_audit_events_result'), ('ck_ckd_registry_entries_closure'), ('ck_ckd_registry_entries_egfr_non_negative'), ('ck_ckd_registry_entries_stage'), ('ck_ckd_registry_outcomes_date_not_future'), ('ck_ckd_registry_outcomes_type'), ('ck_prescriptions_therapy_group'), ('ck_schedule_entries_appointment_type'), ('ck_schedule_entries_status'), ('ck_schedule_entries_time'), ('fk_albuminuria_appointment'), ('fk_appointment_additional_studies_appointment'), ('fk_appointment_diets_appointment'), ('fk_appointment_icd10_diagnoses_appointment'), ('fk_appointment_icd10_diagnoses_icd10'), ('fk_appointments_doctor'), ('fk_appointments_location'), ('fk_appointments_patient'), ('fk_audit_event_changes_event'), ('fk_audit_events_appointment'), ('fk_audit_events_patient'), ('fk_audit_events_user'), ('fk_biochemistry_appointment'), ('fk_branches_company'), ('fk_calculated_metrics_appointment'), ('fk_cbc_appointment'), ('fk_ckd_prognosis_albuminuria_result'), ('fk_ckd_prognosis_appointment'), ('fk_ckd_prognosis_gfr_metric'), ('fk_ckd_registry_entries_closed_by'), ('fk_ckd_registry_entries_included_by'), ('fk_ckd_registry_entries_patient'), ('fk_ckd_registry_outcomes_created_by'), ('fk_ckd_registry_outcomes_entry'), ('fk_doctor_locations_doctor'), ('fk_doctor_locations_location'), ('fk_examinations_appointment'), ('fk_locations_branch'), ('fk_locations_company'), ('fk_prescriptions_appointment'), ('fk_schedule_entries_actual_doctor'), ('fk_schedule_entries_appointment'), ('fk_schedule_entries_cancelled_by'), ('fk_schedule_entries_created_by'), ('fk_schedule_entries_location'), ('fk_schedule_entries_patient'), ('fk_schedule_entries_scheduled_doctor'), ('fk_surveys_appointment'), ('fk_ultrasound_appointment'), ('fk_urinalysis_appointment'), ('fk_users_doctor'), ('fk_users_patient'), ('uq_appointment_diets_appointment'), ('uq_appointment_icd10_diagnoses_position'), ('uq_ckd_registry_entries_patient'), ('uq_doctor_locations_pair'), ('uq_examinations_appointment'), ('uq_icd10_diagnoses_diagnosis'), ('uq_medications_display_name'), ('uq_surveys_appointment'), ('uq_users_login'))
    SELECT string_agg(e.name,', ') INTO problems FROM expected e
      LEFT JOIN pg_constraint c ON c.conname=e.name WHERE c.oid IS NULL;
    IF problems IS NOT NULL THEN RAISE EXCEPTION 'Не созданы ограничения: %',problems; END IF;

    WITH expected(name) AS (VALUES ('idx_albuminuria_appointment_date'), ('idx_albuminuria_appointment_id'), ('idx_appointment_diets_appointment_id'), ('idx_appointment_icd10_diagnoses_appointment_id'), ('idx_appointment_icd10_diagnoses_icd10_id'), ('idx_appointment_icd10_diagnoses_type'), ('idx_appointments_date'), ('idx_appointments_doctor_id'), ('idx_appointments_location_id'), ('idx_appointments_patient_date'), ('idx_appointments_patient_id'), ('idx_biochemistry_appointment_date'), ('idx_biochemistry_appointment_id'), ('idx_branches_company_id'), ('idx_calculated_metrics_appointment_date'), ('idx_calculated_metrics_appointment_id'), ('idx_cbc_appointment_date'), ('idx_cbc_appointment_id'), ('idx_ckd_prognosis_albuminuria_date'), ('idx_ckd_prognosis_appointment_id'), ('idx_ckd_prognosis_assessment_active'), ('idx_ckd_prognosis_assessment_date'), ('idx_ckd_prognosis_gfr_date'), ('idx_ckd_prognosis_matrix_lookup'), ('idx_doctor_locations_doctor_id'), ('idx_doctor_locations_location_id'), ('idx_examinations_appointment_id'), ('idx_icd10_diagnoses_active'), ('idx_icd10_diagnoses_sort_order'), ('idx_icd10_diagnoses_text'), ('idx_locations_branch_id'), ('idx_medications_active_substance'), ('idx_medications_is_active'), ('idx_medications_sort_order'), ('idx_patients_fio'), ('idx_prescriptions_appointment_id'), ('idx_prescriptions_therapy_group'), ('idx_surveys_appointment_id'), ('idx_ultrasound_appointment_date'), ('idx_ultrasound_appointment_id'), ('idx_urinalysis_appointment_date'), ('idx_urinalysis_appointment_id'), ('ix_audit_event_changes_event_id'), ('ix_audit_event_changes_section'), ('ix_audit_event_changes_type'), ('ix_audit_events_action'), ('ix_audit_events_appointment_id'), ('ix_audit_events_created_at'), ('ix_audit_events_patient_id'), ('ix_audit_events_result'), ('ix_audit_events_user_id'), ('ix_ckd_registry_entries_included_at'), ('ix_ckd_registry_entries_is_active'), ('ix_ckd_registry_outcomes_entry_date'), ('ix_ckd_registry_outcomes_type'), ('ix_schedule_entries_doctor_period'), ('ix_schedule_entries_location_period'), ('ix_schedule_entries_patient'), ('ix_schedule_entries_status'), ('uq_ckd_prognosis_active_source_pair'), ('ux_schedule_entries_appointment'))
    SELECT string_agg(e.name,', ') INTO problems FROM expected e
      LEFT JOIN pg_indexes i ON i.schemaname='public' AND i.indexname=e.name WHERE i.indexname IS NULL;
    IF problems IS NOT NULL THEN RAISE EXCEPTION 'Не созданы индексы: %',problems; END IF;

    IF (SELECT array_agg(column_name::text ORDER BY ordinal_position) FROM information_schema.columns
        WHERE table_schema='public' AND table_name='appointment_icd10_diagnoses_view')
       IS DISTINCT FROM ARRAY['id','appointment_id','diagnosis_type','icd10_diagnosis_id','icd10_diagnosis','doctor_note','sort_order','created_at','updated_at']::text[]
    THEN RAISE EXCEPTION 'Неверна структура appointment_icd10_diagnoses_view'; END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                   WHERE n.nspname='public' AND p.proname='set_ckd_prognosis_source_fields')
    THEN RAISE EXCEPTION 'Не создана функция KDIGO'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='trg_set_ckd_prognosis_source_fields' AND NOT tgisinternal)
    THEN RAISE EXCEPTION 'Не создан триггер KDIGO'; END IF;

    SELECT count(*) INTO bad FROM medications; IF bad<>27 THEN RAISE EXCEPTION 'Ожидалось 27 лекарств, получено %',bad; END IF;
    SELECT md5(string_agg(display_name||E'\t'||COALESCE(trade_name,'<NULL>')||E'\t'||COALESCE(active_substance,'<NULL>')||E'\t'||COALESCE(drug_group,'<NULL>')||E'\t'||sort_order::text||E'\t'||is_active::text,E'\n' ORDER BY sort_order,display_name)) INTO actual_hash FROM medications;
    IF actual_hash<>'f354df73c0220018dc863d7e62971b1b' THEN RAISE EXCEPTION 'Изменён справочник лекарств: %',actual_hash; END IF;

    SELECT count(*) INTO bad FROM icd10_diagnoses; IF bad<>155 THEN RAISE EXCEPTION 'Ожидалось 155 записей МКБ, получено %',bad; END IF;
    SELECT md5(string_agg(diagnosis||E'\t'||sort_order::text||E'\t'||is_active::text,E'\n' ORDER BY sort_order,diagnosis)) INTO actual_hash FROM icd10_diagnoses;
    IF actual_hash<>'4e22e7697991d229dfa549663337d4fd' THEN RAISE EXCEPTION 'Изменён справочник МКБ: %',actual_hash; END IF;

    IF (SELECT count(*) FROM companies)<>2 OR (SELECT count(*) FROM branches)<>3 OR (SELECT count(*) FROM locations)<>7 OR (SELECT count(*) FROM doctors)<>12
    THEN RAISE EXCEPTION 'Неверно загружен справочник больницы'; END IF;
    SELECT count(*) INTO bad FROM users WHERE role='registrar' AND login='registrar' AND doctor_id IS NULL AND patient_id IS NULL;
    IF bad<>1 THEN RAISE EXCEPTION 'Не создан регистратор'; END IF;
    IF EXISTS (SELECT 1 FROM users WHERE role='patient') THEN RAISE EXCEPTION 'Роль patient не должна использоваться'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chk_users_role_model' AND pg_get_constraintdef(oid) LIKE '%registrar%' AND POSITION('''patient''' IN pg_get_constraintdef(oid))=0)
    THEN RAISE EXCEPTION 'Не установлена новая ролевая модель'; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='appointments' AND column_name IN ('archive_import_key','archive_source_relative_path','diagnosis_text','diagnosis_comment_text','is_archive_import'))
    THEN RAISE EXCEPTION 'Архивные поля попали в core'; END IF;
END $$;
SELECT 'core_v2_ok' AS result;
